~~~go
type Node[T any] struct {
    Value T
    Next  *Node[T]
}

func reverse[T any](head *Node[T]) *Node[T] {
    var previous *Node[T]
    for current := head; current != nil; {
        next := current.Next
        current.Next = previous
        previous, current = current, next
    }
    return previous
}
